from __future__ import annotations

from decimal import Decimal, localcontext
from types import SimpleNamespace

import pytest

from genai_prices import Usage
from genai_prices.decompose import compute_leaf_values, is_descendant_or_self
from genai_prices.units import UnitRegistry

from .unit_registry_helpers import load_units


def test_decomposition_descendant_helper_accepts_self() -> None:
    registry = UnitRegistry(load_units())

    assert is_descendant_or_self(registry.units['input_tokens'], registry.units['input_tokens'])


def test_decomposition_descendant_helper_accepts_parent_child_pairs() -> None:
    registry = UnitRegistry(load_units())

    assert is_descendant_or_self(registry.units['input_tokens'], registry.units['cache_read_tokens'])
    assert not is_descendant_or_self(registry.units['cache_read_tokens'], registry.units['input_tokens'])


def test_decomposition_descendant_helper_rejects_siblings() -> None:
    registry = UnitRegistry(load_units())

    assert not is_descendant_or_self(registry.units['cache_read_tokens'], registry.units['input_audio_tokens'])


def test_decomposition_descendant_helper_rejects_cross_family_units() -> None:
    registry = UnitRegistry(load_units())

    assert not is_descendant_or_self(registry.units['requests'], registry.units['input_tokens'])


def test_decomposition_descendant_helper_rejects_incompatible_units() -> None:
    registry = UnitRegistry(load_units())

    assert not is_descendant_or_self(registry.units['input_tokens'], registry.units['output_tokens'])


def test_compute_leaf_values_handles_parent_child_decomposition() -> None:
    registry = UnitRegistry(load_units())

    assert compute_leaf_values(
        {'input_tokens', 'cache_read_tokens'},
        Usage(input_tokens=1_000, cache_read_tokens=250),
        registry.units,
    ) == {'cache_read_tokens': 250, 'input_tokens': 750}


def test_compute_leaf_values_handles_cached_audio_overlap() -> None:
    registry = UnitRegistry(load_units())

    assert compute_leaf_values(
        {'input_tokens', 'cache_read_tokens', 'input_audio_tokens', 'cache_audio_read_tokens'},
        Usage(
            input_tokens=1_000,
            cache_read_tokens=400,
            input_audio_tokens=300,
            cache_audio_read_tokens=100,
        ),
        registry.units,
    ) == {
        'cache_audio_read_tokens': 100,
        'cache_read_tokens': 300,
        'input_audio_tokens': 200,
        'input_tokens': 400,
    }


def test_compute_leaf_values_handles_fractional_overlap() -> None:
    registry = UnitRegistry(load_units())

    leaf_values = compute_leaf_values(
        {'input_tokens', 'cache_read_tokens', 'input_audio_tokens', 'cache_audio_read_tokens'},
        Usage(
            input_tokens=0.7,
            cache_read_tokens=0.3,
            input_audio_tokens=0.2,
            cache_audio_read_tokens=0.1,
        ),
        registry.units,
    )

    assert leaf_values == {
        'cache_audio_read_tokens': 0.1,
        'cache_read_tokens': 0.2,
        'input_audio_tokens': 0.1,
        'input_tokens': 0.3,
    }
    assert all(type(value) is float for value in leaf_values.values())


def test_compute_leaf_values_handles_exact_fractional_remainder() -> None:
    registry = UnitRegistry(load_units())

    leaf_values = compute_leaf_values(
        {'input_tokens', 'cache_read_tokens', 'input_audio_tokens'},
        Usage(input_tokens=0.3, cache_read_tokens=0.1, input_audio_tokens=0.2),
        registry.units,
    )

    assert leaf_values['input_tokens'] == 0.0
    assert type(leaf_values['input_tokens']) is float


def test_compute_leaf_values_handles_mixed_integer_and_fractional_values() -> None:
    registry = UnitRegistry(load_units())

    leaf_values = compute_leaf_values(
        {'input_tokens', 'cache_read_tokens'},
        Usage(input_tokens=1, cache_read_tokens=0.25),
        registry.units,
    )

    assert leaf_values == {'cache_read_tokens': 0.25, 'input_tokens': 0.75}
    assert type(leaf_values['input_tokens']) is float


def test_compute_leaf_values_promotes_mixed_decimal_and_float_values() -> None:
    registry = UnitRegistry(load_units())

    leaf_values = compute_leaf_values(
        {'input_tokens', 'cache_read_tokens', 'input_audio_tokens'},
        Usage(input_tokens=Decimal('0.3'), cache_read_tokens=0.1, input_audio_tokens=Decimal('0.2')),
        registry.units,
    )

    assert leaf_values == {
        'cache_read_tokens': 0.1,
        'input_audio_tokens': Decimal('0.2'),
        'input_tokens': Decimal('0.0'),
    }
    assert type(leaf_values['cache_read_tokens']) is float
    assert isinstance(leaf_values['input_audio_tokens'], Decimal)
    assert isinstance(leaf_values['input_tokens'], Decimal)


def test_compute_leaf_values_ignores_ambient_decimal_context() -> None:
    registry = UnitRegistry(load_units())

    with localcontext() as context:
        context.prec = 1
        leaf_values = compute_leaf_values(
            {'input_tokens', 'cache_read_tokens', 'input_audio_tokens'},
            Usage(input_tokens=0.31, cache_read_tokens=0.15, input_audio_tokens=0.16),
            registry.units,
        )

    assert leaf_values['input_tokens'] == 0.0


def test_compute_leaf_values_with_decimal_ignores_ambient_context() -> None:
    registry = UnitRegistry(load_units())

    with localcontext() as context:
        context.prec = 1
        leaf_values = compute_leaf_values(
            {'input_tokens', 'cache_read_tokens', 'input_audio_tokens'},
            Usage(
                input_tokens=Decimal('0.31'),
                cache_read_tokens=Decimal('0.15'),
                input_audio_tokens=Decimal('0.16'),
            ),
            registry.units,
        )

    assert leaf_values['input_tokens'] == Decimal('0.00')


def test_compute_leaf_values_handles_conditional_dimension_chain() -> None:
    registry = UnitRegistry(load_units())

    assert compute_leaf_values(
        {'input_tokens', 'cache_write_tokens', 'cache_write_1h_tokens'},
        Usage(input_tokens=400, cache_write_tokens=300, cache_write_1h_tokens=100),
        registry.units,
    ) == {
        'cache_write_1h_tokens': 100,
        'cache_write_tokens': 200,
        'input_tokens': 100,
    }


def test_compute_leaf_values_handles_output_audio_decomposition() -> None:
    registry = UnitRegistry(load_units())

    assert compute_leaf_values(
        {'output_tokens', 'output_audio_tokens'},
        Usage(output_tokens=700, output_audio_tokens=200),
        registry.units,
    ) == {'output_audio_tokens': 200, 'output_tokens': 500}


def test_compute_leaf_values_handles_deeper_non_boolean_chain() -> None:
    registry = UnitRegistry(
        {
            'tokens': {
                'per': 1,
                'dimensions': {'family': 'tokens'},
            },
            'input_tokens': {
                'per': 1,
                'dimensions': {'family': 'tokens', 'direction': 'input'},
            },
            'cache_read_tokens': {
                'per': 1,
                'dimensions': {'family': 'tokens', 'direction': 'input', 'cache': 'read'},
            },
        }
    )

    assert compute_leaf_values(
        set(registry.units),
        SimpleNamespace(tokens=100, input_tokens=60, cache_read_tokens=20),
        registry.units,
    ) == {'cache_read_tokens': 20, 'input_tokens': 40, 'tokens': 40}


def test_compute_leaf_values_ignores_unpriced_reported_descendants() -> None:
    registry = UnitRegistry(load_units())

    assert compute_leaf_values(
        {'input_tokens'},
        Usage(input_tokens=100, cache_read_tokens=80),
        registry.units,
    ) == {'input_tokens': 100}


def test_compute_leaf_values_rejects_negative_leaf_values() -> None:
    registry = UnitRegistry(load_units())

    with pytest.raises(ValueError, match='cache_read_tokens .* cannot exceed input_tokens'):
        compute_leaf_values(
            {'input_tokens', 'cache_read_tokens'},
            Usage(input_tokens=100, cache_read_tokens=200),
            registry.units,
        )


def test_compute_leaf_values_rejects_materially_negative_fractional_leaf_values() -> None:
    registry = UnitRegistry(load_units())

    with pytest.raises(ValueError, match=r'cache_read_tokens \(0\.2\) cannot exceed input_tokens \(0\.1\)'):
        compute_leaf_values(
            {'input_tokens', 'cache_read_tokens'},
            Usage(input_tokens=0.1, cache_read_tokens=0.2),
            registry.units,
        )


def test_compute_leaf_values_reports_overlapping_contradictions_in_usage_terms() -> None:
    registry = UnitRegistry(load_units())

    with pytest.raises(
        ValueError,
        match=('more-specific usage for cache_read_tokens, input_audio_tokens totals 160, which exceeds input_tokens'),
    ):
        compute_leaf_values(
            {'input_tokens', 'cache_read_tokens', 'input_audio_tokens', 'cache_audio_read_tokens'},
            Usage(input_tokens=100, cache_read_tokens=80, input_audio_tokens=80, cache_audio_read_tokens=0),
            registry.units,
        )

import { describe, expect, it } from 'vitest'

import type { UnitDef } from '../types'

import { computeLeafValues } from '../decompose'
import { getActiveRegistry, isDescendantOrSelf, UnitRegistry } from '../units'
import { normalizeUsage } from '../usage'

describe('isDescendantOrSelf', () => {
  it('accepts the same unit', () => {
    const input = getUnit('input_tokens')
    expect(isDescendantOrSelf(input, input)).toBe(true)
  })

  it('accepts parent and child units', () => {
    expect(isDescendantOrSelf(getUnit('input_tokens'), getUnit('cache_read_tokens'))).toBe(true)
    expect(isDescendantOrSelf(getUnit('input_tokens'), getUnit('input_audio_tokens'))).toBe(true)
  })

  it('rejects siblings', () => {
    expect(isDescendantOrSelf(getUnit('cache_read_tokens'), getUnit('input_audio_tokens'))).toBe(false)
  })

  it('rejects cross-family units', () => {
    expect(isDescendantOrSelf(getUnit('requests'), getUnit('input_tokens'))).toBe(false)
  })

  it('rejects incompatible units', () => {
    expect(isDescendantOrSelf(getUnit('input_tokens'), getUnit('output_tokens'))).toBe(false)
  })
})

describe('computeLeafValues', () => {
  it('handles parent/child decomposition', () => {
    expect(
      computeLeafValues(
        new Set(['cache_read_tokens', 'input_tokens']),
        normalizeUsage({
          cache_read_tokens: 250,
          input_tokens: 1_000,
        }),
        getActiveRegistry()
      )
    ).toEqual({
      cache_read_tokens: 250,
      input_tokens: 750,
    })
  })

  it('handles cached-audio overlap decomposition', () => {
    expect(
      computeLeafValues(
        new Set(['cache_audio_read_tokens', 'cache_read_tokens', 'input_audio_tokens', 'input_tokens']),
        normalizeUsage({
          cache_audio_read_tokens: 100,
          cache_read_tokens: 400,
          input_audio_tokens: 300,
          input_tokens: 1_000,
        }),
        getActiveRegistry()
      )
    ).toEqual({
      cache_audio_read_tokens: 100,
      cache_read_tokens: 300,
      input_audio_tokens: 200,
      input_tokens: 400,
    })
  })

  it('handles a conditional-dimension chain', () => {
    expect(
      computeLeafValues(
        new Set(['cache_write_1h_tokens', 'cache_write_tokens', 'input_tokens']),
        normalizeUsage({
          cache_write_1h_tokens: 100,
          cache_write_tokens: 300,
          input_tokens: 400,
        }),
        getActiveRegistry()
      )
    ).toEqual({
      cache_write_1h_tokens: 100,
      cache_write_tokens: 200,
      input_tokens: 100,
    })
  })

  it('handles output audio decomposition', () => {
    expect(
      computeLeafValues(
        new Set(['output_audio_tokens', 'output_tokens']),
        normalizeUsage({
          output_audio_tokens: 200,
          output_tokens: 700,
        }),
        getActiveRegistry()
      )
    ).toEqual({
      output_audio_tokens: 200,
      output_tokens: 500,
    })
  })

  it('handles reasoning-modality overlap decomposition', () => {
    expect(
      computeLeafValues(
        new Set(['output_reasoning_tokens', 'output_text_reasoning_tokens', 'output_text_tokens', 'output_tokens']),
        normalizeUsage({
          output_reasoning_tokens: 30,
          output_text_reasoning_tokens: 20,
          output_text_tokens: 60,
          output_tokens: 100,
        }),
        getActiveRegistry()
      )
    ).toEqual({
      output_reasoning_tokens: 10,
      output_text_reasoning_tokens: 20,
      output_text_tokens: 40,
      output_tokens: 30,
    })
  })

  it('handles conditional-dimension chains without parity assumptions', () => {
    const registry = new UnitRegistry({
      cache_write_1h_tokens: {
        dimensions: {
          cache_ttl: '1h',
          direction: 'input',
          family: 'tokens',
          token_type: 'cache_write',
        },
        per: 1,
      },
      cache_write_tokens: {
        dimensions: {
          direction: 'input',
          family: 'tokens',
          token_type: 'cache_write',
        },
        per: 1,
      },
      input_tokens: {
        dimensions: {
          direction: 'input',
          family: 'tokens',
        },
        per: 1,
      },
    })

    expect(
      computeLeafValues(
        new Set(['cache_write_1h_tokens', 'cache_write_tokens', 'input_tokens']),
        normalizeUsage(
          {
            cache_write_1h_tokens: 20,
            cache_write_tokens: 60,
            input_tokens: 100,
          },
          registry
        ),
        registry
      )
    ).toEqual({
      cache_write_1h_tokens: 20,
      cache_write_tokens: 40,
      input_tokens: 40,
    })
  })

  it('normalizes negligible floating-point residuals to zero', () => {
    expect(
      computeLeafValues(
        new Set(['input_audio_tokens', 'input_image_tokens', 'input_tokens']),
        normalizeUsage({
          input_audio_tokens: 0.2,
          input_image_tokens: 0.1,
          input_tokens: 0.3,
        }),
        getActiveRegistry()
      )
    ).toEqual({
      input_audio_tokens: 0.2,
      input_image_tokens: 0.1,
      input_tokens: 0,
    })
  })

  it('rejects fractional descendants that exceed their parent', () => {
    expect(() =>
      computeLeafValues(
        new Set(['cache_read_tokens', 'input_tokens']),
        normalizeUsage({
          cache_read_tokens: 0.2,
          input_tokens: 0.1,
        }),
        getActiveRegistry()
      )
    ).toThrow('Invalid usage data: cache_read_tokens (0.2) cannot exceed input_tokens (0.1)')
  })

  it('ignores unpriced reported descendants when priced ancestors cover them', () => {
    expect(
      computeLeafValues(
        new Set(['input_tokens']),
        normalizeUsage({
          cache_read_tokens: 80,
          input_tokens: 100,
        }),
        getActiveRegistry()
      )
    ).toEqual({
      input_tokens: 100,
    })
  })

  it('rejects direct descendants that exceed their parent', () => {
    expect(() =>
      computeLeafValues(
        new Set(['cache_read_tokens', 'input_tokens']),
        normalizeUsage({
          cache_read_tokens: 200,
          input_tokens: 100,
        }),
        getActiveRegistry()
      )
    ).toThrow('Invalid usage data: cache_read_tokens (200) cannot exceed input_tokens (100)')
  })

  it('rejects overlapping descendant totals that exceed their parent', () => {
    expect(() =>
      computeLeafValues(
        new Set(['cache_audio_read_tokens', 'cache_read_tokens', 'input_audio_tokens', 'input_tokens']),
        normalizeUsage({
          cache_audio_read_tokens: 0,
          cache_read_tokens: 80,
          input_audio_tokens: 80,
          input_tokens: 100,
        }),
        getActiveRegistry()
      )
    ).toThrow(
      'Invalid usage data: more-specific usage for cache_read_tokens, input_audio_tokens totals 160, which exceeds input_tokens (100)'
    )
  })
})

function getUnit(usageKey: string): UnitDef {
  const unit = getActiveRegistry().getUnit(usageKey)
  if (!unit) throw new Error(`Missing test unit for ${usageKey}`)
  return unit
}

from __future__ import annotations

from decimal import Decimal

import pytest
from inline_snapshot import snapshot
from pydantic import TypeAdapter, ValidationError

from prices.source_litellm import LiteLLMModel, get_litellm_prices, lite_llm_response_schema

from .fixtures import capture_source_prices, load_mapping, load_payload, mock_httpx_get

LITELLM_URL = 'https://raw.githubusercontent.com/BerriAI/litellm/refs/heads/main/model_prices_and_context_window.json'

# LiteLLM's payload is keyed by model name but carries two entries that are not models: a documentation
# template whose values are prose placeholders, and a block of routing rules. `OnErrorOmit` exists to
# skip exactly these — any *other* key it starts skipping is silent data loss.
NON_MODEL_ENTRIES = {'sample_spec', 'fallback_generalizations'}

_strict_model_schema = TypeAdapter(LiteLLMModel)


@pytest.mark.parametrize(
    ('reasoning_per_token', 'expected_reasoning_mtok'),
    [
        (Decimal('0.000003'), Decimal('3')),
        (Decimal('0.000002'), None),
        (None, None),
    ],
)
def test_litellm_model_price_preserves_only_distinct_reasoning_rate(
    reasoning_per_token: Decimal | None,
    expected_reasoning_mtok: Decimal | None,
):
    model = LiteLLMModel(
        input_cost_per_token=Decimal('0.000001'),
        output_cost_per_token=Decimal('0.000002'),
        output_cost_per_reasoning_token=reasoning_per_token,
        litellm_provider='test',
    )

    expected = {'input_mtok': Decimal('1'), 'output_mtok': Decimal('2')}
    if expected_reasoning_mtok is not None:
        expected['output_reasoning_mtok'] = expected_reasoning_mtok
    assert model.model_price().model_dump(exclude_none=True) == expected


def test_litellm_payload_drops_no_models():
    """`lite_llm_response_schema` uses `OnErrorOmit`, so schema drift costs us models with no error at all.

    Counting raw entries against decoded ones is the assertion that turns that silence into a failure.
    """
    raw = load_mapping('litellm_models.json')
    decoded = lite_llm_response_schema.validate_json(load_payload('litellm_models.json'))

    expected_models = set(raw) - NON_MODEL_ENTRIES
    assert set(decoded) == expected_models
    assert len(decoded) == len(raw) - len(NON_MODEL_ENTRIES)


def test_litellm_payload_models_also_decode_strictly():
    """Every real model must satisfy the schema *without* `OnErrorOmit` covering for it."""
    raw = load_mapping('litellm_models.json')

    for name, entry in raw.items():
        if name in NON_MODEL_ENTRIES:
            continue
        _strict_model_schema.validate_python(entry)


@pytest.mark.parametrize('name', sorted(NON_MODEL_ENTRIES))
def test_litellm_non_model_entries_are_the_only_expected_drops(name: str):
    """Pins *why* `OnErrorOmit` is tolerable here: these two entries are not models and cannot validate."""
    entry = load_mapping('litellm_models.json')[name]

    with pytest.raises(ValidationError):
        _strict_model_schema.validate_python(entry)


def test_litellm_prices_map_providers_and_skip_unpriced(monkeypatch: pytest.MonkeyPatch):
    """Runs the importer end-to-end on the recorded payload, capturing the write instead of performing it."""
    mock_httpx_get(monkeypatch, expected_url=LITELLM_URL, content=load_payload('litellm_models.json'))
    written = capture_source_prices(monkeypatch)

    get_litellm_prices()

    assert {
        provider: {name: price.model_dump(exclude_none=True) for name, price in models.items()}
        for provider, models in written['litellm'].items()
    } == snapshot(
        {
            'google': {
                'gemini/gemini-robotics-er-1.5-preview': {
                    'input_mtok': Decimal('0.30'),
                    'output_mtok': Decimal('2.50'),
                },
                'vertex_ai/claude-3-5-haiku': {'input_mtok': Decimal('1'), 'output_mtok': Decimal('5')},
            },
            'aws': {'us.writer.palmyra-x4-v1:0': {'input_mtok': Decimal('2.50'), 'output_mtok': Decimal('10')}},
            'x-ai': {'xai/grok-2': {'input_mtok': Decimal('2'), 'output_mtok': Decimal('10')}},
            'azure': {'azure/eu/gpt-4o-2024-08-06': {'input_mtok': Decimal('2.75'), 'output_mtok': Decimal('11')}},
        }
    )


def test_litellm_prices_skip_entries_the_importer_cannot_use(monkeypatch: pytest.MonkeyPatch):
    """The recorded payload deliberately includes entries the importer must drop, so the mapping above is
    an assertion about filtering rather than a coincidence of the sample."""
    mock_httpx_get(monkeypatch, expected_url=LITELLM_URL, content=load_payload('litellm_models.json'))
    written = capture_source_prices(monkeypatch)

    get_litellm_prices()

    imported = {name for models in written['litellm'].values() for name in models}
    # no per-token cost at all, so there is no price to record
    assert '1024-x-1024/50-steps/stability.stable-diffusion-xl-v1' not in imported
    # `litellm_provider` values with no provider YAML of their own
    assert 'ollama/codegeex4' not in imported
    assert 'dashscope/qwen-plus-2025-04-28' not in imported

