		{model: "gpt-5.5-pro", baseRate: 30, longRate: 60},
		{model: "gpt-5.6-luna", baseRate: 0.2, longRate: 0.4},
		{model: "gpt-5.6-sol", baseRate: 4, longRate: 8},
