			},
			Model:      "~anthropic/claude-haiku-latest",
			ProviderID: "openrouter",
			Timestamp:  test.timestamp,
		})
		if err != nil {
			t.Fatal(err)
		}
		if math.Abs(calculation.TotalPrice-test.want) > 1e-9 {
